-- Hexagram text group 1: compact lazy-loaded records.
return {
  ["地天泰"] = { index="第11卦", name="地天泰", shortName="泰卦", subtitle="应时而变", rating="中中卦",
  xiang="学文满腹入场闱，三元及第得意回，从今解去愁和闷，喜庆平地一声雷。", summary="这个卦是异卦（下乾上坤）相叠，乾为天，为阳；坤为地，为阴，阴阳交感，上下互通，天地相交，万物纷纭。反之则凶。万事万物，皆对立，转化，盛极必衰，衰而转盛，故应时而变者泰（通）。",
  career="坚持由小而大，循序渐进的原则，事业已达到顺利的境地，更应小心从事，居安思危，积极寻求、开拓新的事业，方可继续前进，若因循守旧，不思进取，必遭失败。", business="顺利。务必注意市场动向，开拓新的领域，展开新的竞争。为此，密切与他人的合作，争取各方面的帮助，但需谦虚谨慎，警惕巧言令色的小人。",
  fame="具有成功的条件，但一定得更加努力，刻苦追求，最忌聪明反被聪明误。", travel="一帆风顺。", marriage="美满姻缘。谈恋爱却不可不认真对待。",
  decision="吉祥如意。适应能力强，各项事业能成功。能谋善断，长于人际关系，能团结他人共创业绩，灵活机动，很能适应形势的变化，不断向新的领域迈进。但在人生途中必须兢兢业业，尤其不可麻痹大意，在择朋选友方面更应慎重，切防小人倒运。" },
  ["风天小畜"] = { index="第9卦", name="风天小畜", shortName="小畜卦", subtitle="蓄养待进", rating="下下卦",
  xiang="苗逢旱天尽焦梢，水想云浓雨不浇，农人仰面长吁气，是从款来莫心高。", summary="这个卦是异卦（下乾上巽）相叠，乾为天；巽为风。喻风调雨顺，谷物滋长，故卦名小畜（蓄）。力量有限，须待发展到一定程度，才可大有作为。",
  career="时机尚不成熟，应当耐心而积极地积存力量，切不可冒险行动。遇到挫折不可灰心，鼓起勇气战胜困难，坚持原则，加强团结合作，提前做好各项准备，会有所成。", business="已有一定的基础，但有失去危险，一定要特别慎重，争取与他人真诚合作，共同获利，决不贪心，适可而止，但更不能满足现状，不图进取。",
  fame="树立远大目标，尽最大努力去争取，虚心求教他人，取得真诚帮助，实现自己的理想，警惕小人的破坏。", travel="准备尚未充分，不得仓促出行，尤其忌长途旅行，会有意外的灾害。应另择他日外出。", marriage="双方必须十分忠诚，第三者插足的现象极有可能发生。",
  decision="不很顺利，前进途中会遇到一些意想不到的困难。但由于本人性格坚强，具有战胜不利条件的意志。因此，可以实理自己的理想。但极有可能遭到小人的伤害，必须得到志同道合者的真诚相助，才能可能排除障碍。对所得应满足，适可而止，切不可过度追求，以免满招损。" },
  ["火天大有"] = { index="第14卦", name="火天大有", shortName="大有卦", subtitle="顺天依时", rating="上上卦",
  xiang="砍树摸雀作事牢，是非口舌自然消，婚姻合伙来费力，若问走失未逃脱。", summary="这个卦是异卦（下乾上离）相叠。上卦为离，为火；下卦为乾，为天。火在天上，普照万物，万民归顺，顺天依时，大有所成。",
  career="事业已经取得一定的成就，最忌得意忘形，胡作非为。务必止恶扬善，坚守中止，交往正直的朋友，戒惧谨慎，兢兢业业，真正做到大而不盈，满而不溢，事业可望迈上新的台阶。", business="兴隆昌盛，已摆脱困难状态，进入兴旺发达的阶段，如能克制贪财的心理，确守诚信原则，公平待人，克勤克俭，尤其应时刻注意市场动向，适时转轨，可望长久。",
  fame="已经小有名气，切勿就此满足，停顿不前，尤其不可陷入世俗圈内，应继续努力，在真正朋友的帮助下，更上一层楼。", travel="平安，可动身。", marriage="条件优越，可供选择者多，以慎重为好。对于家庭双方应尽力维护。",
  decision="性格坚强，勇于战胜困难，奋斗向上，前进途中困难和厄运很多，唯有认真对待才能不断取得成功，如放松警惕，骄傲自满，将带来惨重失败。朋友很多，交际广泛，对事业很有帮助，但其中也有拆台的小人。" },
  ["雷天大壮"] = { index="第34卦", name="雷天大壮", shortName="大壮卦", subtitle="壮勿妄动", rating="中上卦",
  xiang="卦占工师得大木，眼前该着走上路，时来运转多顺当，有事自管放心宽。", summary="这个卦是异卦（下乾上震）相叠。震为雷；乾为天。乾刚震动。天鸣雷，云雷滚，声势宏大，阳气盛壮，万物生长。刚壮有力故曰壮。大而且壮，故名大壮。四阳壮盛，积极而有所作为，上正下正，标正影直。",
  career="处世凭智不凭力，有勇更有谋，切忌蛮干，该守不守，自取其凶。不可逞强，否则自取凶险。对小人应有防犯，尤其不得忽视小人的奸诈。对事业应勇往直前，但切忌冒进。", business="处在高涨阶段，形势很好。但决不可逞强，更不可妄动，应主动增强与他人的合作。提高警惕，认识物极必反的道理，做事业衰退的准备。",
  fame="务必注意妥善地运用自己的力量，不可自恃刚健强壮而冒进。尤其不可自负。适当发挥自己的才干，加上外力的援助，必有所作为。", travel="慎重外出，不可莽撞，否则不吉利。", marriage="决不可因自己条件好而高傲。切勿错过好姻缘。",
  decision="强健适中，不可过分消耗自己的力量。在事业顺利的时刻，尤其不可妄动。更应注意，很可能已经处于进退维谷的状态，务必自保待机，及早有所准备。" },
  ["乾为天"] = { index="第1卦", name="乾为天", shortName="乾卦", subtitle="刚健中正", rating="上上卦",
  xiang="困龙得水好运交，不由喜气上眉梢，一切谋望皆如意，向后时运渐渐高。", summary="这个卦是同卦（下乾上乾）相叠。象征天，喻龙（德才的君子），又象征纯粹的阳和健，表明兴盛强健。乾卦是根据万物变通的道理，以“元、亨、利、贞”为卦辞，示吉祥如意，教导人遵守天道的德行。",
  career="大吉大利，万事如意，心想事成，自有天佑，春风得意，事业如日中天。但阳气已达顶点，盛极必衰，务须提高警惕，小心谨慎。力戒骄傲，冷静处世，心境平和，如是则能充分发挥才智，保证事业成功。", business="十分顺利，有发展向上的大好机会。但切勿操之过急，宜冷静分析形势，把握时机，坚持商业道德，冷静对待中途出现的困难，定会有满意的结果。",
  fame="潜在能力尚未充分发挥，只要进一步努力，克服骄傲自满情绪，进业修德，以渊博学识和高尚品质，成君子之名。", travel="利于出行，结伴而行更佳。", marriage="阳盛阴衰，但刚柔可相济，形成美满结果。女性温柔者更佳。",
  decision="可成就大的事业。坚持此卦的刚健、正直、公允的实质，修养德行，积累知识，坚定信念，自强不息，必能克服困难，消除灾难。" },
  ["山天大畜"] = { index="第26卦", name="山天大畜", shortName="大畜卦", subtitle="止而不止", rating="中上卦",
  xiang="忧愁常锁两眉头，千头万绪挂心间，从今以后防开阵，任意行而不相干。", summary="这个卦是异卦（下乾上艮）相叠。乾为天，刚健；艮为山，笃实。畜者积聚，大畜意为大积蓄。为此不畏严重的艰难险阻，努力修身养性以丰富德业。",
  career="务必端正行为，滋养德行。行为应大胆，果断，但需适可而止，注意休整，决不可冒险闯进。宜注意吸收前人的经验教训，有所畏而不行，否则必有危害。再取得成就之后，应适可而止，不可贪图眼前小利而走向反面。", business="本着循序渐进的原则，把握正当的商业道德，会有重大收获。此时，切忌贪心不足，而应见机而退，保守事业，深思熟虑，再图发展，一味自信冒进，决不可取。",
  fame="注意积累学问，提高德行，勿三天打鱼两天晒网，持之以恒，且以学问、知识报效国家，抱负终将实现。", travel="不宜守于家中，出行必得，且畅通无阻。不过应处处小心谨慎。", marriage="顺利。建立在共同勤俭持家的基础上，相互坦诚而待，美满幸福。",
  decision="蓄财的人，但决不可抱投机取巧心理，得靠个人诚实工作，多动心机，真诚与他人合作，共创事业，困难时仍应持正道，尤其不可粗心大意，牢记成就大阻力也大的道理。" },
  ["水天需"] = { index="第5卦", name="水天需", shortName="需卦", subtitle="守正待机", rating="中上卦",
  xiang="明珠土埋日久深，无光无亮到如今，忽然大风吹土去，自然显露有重新。", summary="这个卦是异卦（下乾上坎）相叠，下卦是乾，刚健之意；上卦是坎，险陷之意。以刚逢险，宜稳健之妥，不可冒失行动，观时待变，所往一定成功。",
  career="关键在于审时度势，耐心等待，事成于安祥，切勿冒险，欲速不达。自己要充满自信，临危不惧，坚守中正，必可化险为夷。情况有利时，仍得居安思危。", business="行动之初，情况困难，必须以极大的耐心，创造条件和机会，行事光明磊落，观时待变，实现愿望。事情接近成功时，更应小心谨慎，切莫功亏一篑。",
  fame="时机尚不成熟，应耐心等待。这时应坚定信念，不为闲言流语所动摇，努力丰富自己，再求助可靠的人便可成功。", travel="充分准备齐全后，可平安无事。", marriage="慎重，切不可草率行事，逐渐培养感情，以诚实、热情相待，会发生变故，仍可以有良好的结局。双方都应懂得以柔克刚的道理。",
  decision="前途光明，有雄心大志，且可实现。为此需要积蓄实力，等待时机，大器晚成。本人具有坚强的意志，冷静静的头脑。前进途中会遇到困难和险阻，必须十分谨慎，坦然对待小人的中伤，在灾祸在面前能镇静自若。不轻举妄动，冷静选择方向。为人谦和、坦率，多有他人相助，促使事业成功。当时机，必然一帆风顺。" },
  ["泽天夬"] = { index="第43卦", name="泽天夬", shortName="夬卦", subtitle="决而能和", rating="上上卦",
  xiang="蜘蛛脱网赛天军，粘住游蜂翅翎毛，幸有大风吹破网，脱离灾难又逍遥。", summary="这个卦是异卦（下乾上兑）相叠。乾为天为健；兑为泽为悦。泽气上升，决注成雨，雨施大地，滋润万物。五阳去一阴，去之不难，决（去之意）即可，故名为夬（guài），夬即决。",
  career="处在兴盛阶段，但已孕育着普遍的危险。务必施恩泽给他人，勿居功自傲，主动团结他人，不干冒险的事。时时提高警惕，防止小人的破坏。但不可莽撞，应持和缓的手段去决断小人，避免过犹不及。", business="市场正在走向衰落的状态，不宜大量活动，随时注意转向。开拓新领域时，加强同他人的合作。但务必充分注意别有用心的奸诈小人趁机捣乱和破坏。",
  fame="虚心求教，充实自身实力。但应量力而行，不可盲目自大。更不可同小人合流，徒虚名而败坏事业。", travel="不宜过于频繁，以逸待劳最佳。外出旅行吉利。", marriage="防止上介绍人的当，也应注意对方的目的。",
  decision="性格矛盾，往往表面刚强而内心虚弱，在关键的时刻，败坏事业。虚心听取他人劝告，切勿鲁莽，多谋深思，用柔和的态度待人处世。" },
  ["地泽临"] = { index="第19卦", name="地泽临", shortName="临卦", subtitle="教民保民", rating="中上卦",
  xiang="君王无道民倒悬，常想拨云见青天，幸逢明主施仁政，重又安居乐自然。", summary="这个卦是异卦（下兑上坤）相叠。坤为地；兑为泽，地高于泽，泽容于地。喻君主亲临天下，治国安邦，上下融洽。",
  career="正是成功的极好时机，务必抓紧，不可失去良机。但却不可就此满足，时运会很快消失，一定要从长计议，注意总结经验，团结他人，共同开拓新领域。", business="会十分顺利，并有收获，但须随时注意市场动向，兢兢业业，防止出现意外的事故，尤其应妥善处理人际关系。",
  fame="自己的努力已到了收获的季节，应更加虚心，严格要求自己，谨慎小心地实现自己的目标。很可能出现意外，应以刚强的意志去从容对付，过于软弱将失去机会。", travel="在准备充分的情况下，立即行动，不必再犹豫。", marriage="加紧进行，全力以赴，双方以诚信相待，美满、和谐。",
  decision="头脑灵活，善于同他人交往，并有主见，具有领导才能。务必加强个人的全面修养，诚信待人，树立良好的个人威望，尤其要有远大的眼光，长久的计划，可以保证事业的发达和前程的光明。所作为，甚至不惜冒险，挽救败落状况。必要时还需耐心等待时机。" },
  ["兑为泽"] = { index="第58卦", name="兑为泽", shortName="泽卦", subtitle="刚内柔外", rating="上上卦",
  xiang="这个卦象真可取，觉着做事不费力，休要错过这机关，事事觉得随心意。", summary="这个卦是同卦（下泽上泽）相叠。泽为水。两泽相连，两水交流，上下相和，团结一致，朋友相助，欢欣喜悦。兑为悦也。同秉刚健之德，外抱柔和之姿，坚行正道，导民向上。",
  career="由于善长人际关系，能团结他人，获得援助。因此，各项事业都十分顺利。只要本人坚持中正之道，动机纯正，是非分明，以诚心与人和悦，前途光明。", business="很有利。可以取得多种渠道的支持。但在顺利时切莫忘记谨慎小心的原则，尤其警惕上小人的当。",
  fame="只要自己目的纯正，并有真才实学，一定可以受到多方面的热情帮助和资助，实现追求目的。", travel="一路平安，即使遇到困难也会有人帮助，解脱困境。", marriage="彼此满意，成功的可能性很大。但千万不要过于坚持己见。",
  decision="为人聪颖，性格开朗，头脑灵活，心地善良，热心为公众服务，富有组织才能。因此，可以比较顺利地走上领导岗位。但一定要坚持中正原则，秉公办事，不得诌媚讨好上级，更不可欺压民众。永远保持谦虚品德，尤其不可过分自信，否则很容易为坏人包围。" },
  ["风泽中孚"] = { index="第61卦", name="风泽中孚", shortName="中孚卦", subtitle="诚信立身", rating="下下卦",
  xiang="路上行人色匆匆，急忙无桥过薄冰，小心谨慎过得去，一步错了落水中。", summary="这个卦是异卦（下兑上巽）相叠 。孚（fú）本义孵，孵卵出壳的日期非常准确，有信的意义。卦形外实内虚，喻心中诚信，所以称中孚卦。这是立身处世的根本。",
  career="以诚实忠信的态度对待事业，获得重大的成就，发展顺利。必须继续遵循正道的原则，不可掉以轻心，也不可过分地相信人，尤其不可以孤傲的性格自我封闭。否则事业将走向失败。", business="处理得很好，符合市场的要求。小心谨慎地经营，讲究信义，优质服务，可有满意的结果，甚至冒险犯难也不会出问题。",
  fame="必须在道德修养的基础上，刻苦学习知识和本领，不断提高自己。同时，不要惧怕困难，努力向前。", travel="非常顺利，根据工作的需要可以经常外出。", marriage="双方以诚信的态度相互对待，幸福美满。",
  decision="以诚信为立身处世的基石，真诚待人，信守制度，坚持原则，和悦谦虚，可以战胜任何困难，即使出现了问题也可以亡羊补牢。但务必增强对人的观察能力，提高分辨是非的水平。" },
  ["火泽睽"] = { index="第38卦", name="火泽睽", shortName="睽卦", subtitle="异中求同", rating="下下卦",
  xiang="此卦占来运气歹，如同太公作买卖，贩猪牛快贩羊迟，猪羊齐贩断了宰。", summary="这个卦是异卦（下兑上离）相叠。离为火；兑为泽。上火下泽，相违不相济。克则生，往复无空。万物有所不同，必有所异，相互矛盾。睽即矛盾。",
  career="事业开创困难，处境艰辛。如能志同道合，相互信任，目的可以达到。但起初成功的多是小事。小事积累可成大事。事成于协力合作，败于众志相异。应加强团结，委曲以求相通。最忌内部相互猜疑。", business="应以心平气和的态度投入市场竞争，求大同而存小异。对竞争对手不应敌视，可和而不流，群而不党。尤其不能惹起纠纷，极力避免灾祸。",
  fame="以真诚的心努力上进。对于恶人必要时亦不可完全不交往，应采取宽大包容的态度，适度往来。对志同道合者也不必完全一致，可异中求同。", travel="顺利。途中可以得到善人相助。", marriage="双方必真诚相待。否则，第三者极易介入，夫妻相疑则家破。",
  decision="处于矛盾、对应状态。必须注意以宽宏大度、平和、柔顺的态度对待人生。这样才能心平气和，柔而上进。认清合必有离，离必有合；同中有异，异中有同的道理。否则，刚极暴躁，明极生疑。暴疑皆可致命。" },
  ["雷泽归妹"] = { index="第54卦", name="雷泽归妹", shortName="归妹卦", subtitle="立家兴业", rating="下下卦",
  xiang="求鱼须当向水中，树上求之不顺情，受尽爬揭难随意，劳而无功运平平。", summary="这个卦是异卦（下兑上震）相叠。震为动、为长男；兑为悦、为少女。以少女从长男，产生爱慕之情，有婚姻之动，有嫁女之象，故称归妹。男婚女嫁，天地大义，人的开始和终结。上卦与渐卦为综卦，交互为用。",
  career="正在进入新的阶段，很快将会出现另一番景象。这时首先必须具备远大眼光，识破利弊和吉凶，有备始能无患。其次是坚守纯正的品德和正确的原则。", business="开拓新的市场即将成功。在未来的商业活动中必须注意经营的方向和种类，加强与他人合作。",
  fame="务必以坚定的决心，努力提高自己，为成名立业奠定基础，最可怕是儿女情长影响了自己的前途和事业。", travel="十分顺利，即便发生意外也会有人相助。", marriage="顺其自然，不可违背原则，尤其不可强求，宁可晚婚也要选择理想的对象。夫妻经过生活考验，可和谐到老。",
  decision="对于人生必须坚持公正纯洁的品德，正确对待婚姻和家庭，以幸福美满的家庭为基础，开拓和发展自己的事业。" },
  ["山泽损"] = { index="第41卦", name="山泽损", shortName="损卦", subtitle="损益制衡", rating="下下卦",
  xiang="时动不至费心多，比作推车受折磨，山路崎岖吊下耳，做插右按按不着。", summary="这个卦是异卦（下兑上艮）相叠。艮为山；兑为泽。上山下泽，大泽浸蚀山根。损益相间，损中有益，益中有损。二者之间，不可不慎重对待。损下益上，治理国家，过度会损伤国基。应损则损，但必量力、适度。少损而益最佳。",
  career="开拓事业必有投入。投入多少应事先精心算计，力求损益得当。诸事皆应有节度，切忌欺诈、贪婪。天下事克已最难，务严格要求自己，刻苦奋斗，手段灵活，争取事业成功。", business="全面调查市场行情，计算投入和收益的比例。不必过于计较利润的多少，获利即可。真诚与他人合作，彼此信任，手段灵活，切勿自我封闭。",
  fame="为了成长进步，务必有所投入，且应付诸实践。以损增益，成就理想。", travel="有益可行。注意节省费用，防止损多于益。", marriage="全面权衡对方的长处与短处。大处着眼。",
  decision="为人聪颖，善于权衡利弊。顺应自然发展规律，积极主动与他人合作，助人为乐，适度投入，资助他人，而自己要宁俭勿奢。如此，诸事都可以十分顺利。" },
  ["水泽节"] = { index="第60卦", name="水泽节", shortName="节卦", subtitle="万物有节", rating="上上卦",
  xiang="时来运转喜气生，登台封神姜太公，到此诸神皆退位，纵然有祸不成凶。", summary="这个卦是异卦（下兑上坎）相叠。兑为泽，坎为水。泽有水而流有限，多必溢于泽外。因此要有节度，故称节。节卦与涣卦相反，互为综卦，交相使用。天地有节度才能常新，国家有节度才能安稳，个人有节度才能完美。",
  career="正处在发展时期，一定要注意切勿冒进。但更不应放弃良好的机遇，只要坚持遵利守义的原则，可大胆行动。这样，事业可以继续兴旺发达。", business="市场行情好，对自己很有利，应该努力开拓，勿失去机会。不过，头脑一定要冷静，投入应有限度，适可而止，该收则收。",
  fame="严格要求自己，办事知道节度，不走极端，可以通行无阻，顺利前进。", travel="大胆外出顺利。", marriage="不要陷入情不自禁的地步，顺其自然会有好结果。",
  decision="抓住机遇，勿失良机。适当节制自己的行动，不可勉强，更不可冒险，恰如其分。一切不可拘泥，该变就变。但是，该节制的时候一定要节制。节制必须有限度，过于节制就成为苦，不会有好的结果，这叫适得其反，务必十分注意。" },
  ["天泽履"] = { index="第10卦", name="天泽履", shortName="履卦", subtitle="脚踏实地", rating="中上卦",
  xiang="凤凰落在西歧山，去鸣几声出圣贤，天降文王开基业，富贵荣华八百年。", summary="这个卦是异卦（下兑上乾）相叠，乾为天；兑为泽，以天喻君，以泽喻民，原文：“履（踩）虎尾、不咥（咬）人。”因此，结果吉利。君上民下，各得其位。兑柔遇乾刚，所履危。履意为实践，卦义是脚踏实地的向前进取的意思。",
  career="起初很不顺利，受到种种威胁，若能提高警惕，谨小慎微，脚踏实地，逐个地去克服困难，不改变自己的决心，一定可以达到目的。办事有自知之明，务必量力而行，不可不顾实际，尤其不得逞强，急于求成。", business="宜待观动静，勿为小利而动摇自己计划，尤其不得贪得无厌，遵循商业道德，了解全面信息。",
  fame="务必有恒心，孜孜以求，不为财富利诱，不为世俗干扰，坚持自己的志向和理想，可以取得成功。", travel="有惊无险，可以外出，但非紧急情况可以缓行。", marriage="双方安贫乐道，可和睦相处，若一方为富贵所动，会发生婚变。",
  decision="诸事必须小心慎重，不利的情况经常会出现，但若能处理得好，总会是有惊无险，化险为夷。为此，办事必须认认真真，遵循正道，虚心听取别人的建议，量力而行，切莫自负逞强，一定会有好的结果。" },
}
